const names=['Mittelwerte bestimmen','Messdaten darstellen','Funktionstyp vermuten','Vermutung prüfen und erste Näherung machen','Gleichung bestimmen','Runden & Einheiten'];
const descriptions=['Mehrere Messreihen zusammenführen.','Punkte, Achsen und Balken richtig zeichnen.','Fünf typische Verläufe vergleichen.','Prüfen, analog nähern und Einheiten herleiten.','Parameter mit einer Regression bestimmen.','Aus Zahlen eine physikalische Gleichung machen.'];
const F=s=>`<span class="formula">${s}</span>`;
const frac=(a,b)=>`<span class="frac"><span>${a}</span><span>${b}</span></span>`;
const box=(title,text,kind='note')=>`<div class="callout ${kind}"><strong>${title}</strong><p>${text}</p></div>`;
const table=(heads,rows)=>`<div class="table-wrap" tabindex="0" role="region" aria-label="Datentabelle, bei Bedarf seitlich scrollen"><table><thead><tr>${heads.map(x=>`<th scope="col">${x}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(x=>`<td>${x}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
const detail=(title,text)=>`<details><summary>${title}</summary><div>${text}</div></details>`;
const sections=[];
sections.push(`<p class="lead">Mehrfach gemessen? Fasse für jeden gleichen x-Wert die zugehörigen y-Werte zusammen – wenn die Bedingungen gleich waren.</p><div class="two-col"><article class="card"><h3>Der arithmetische Mittelwert</h3>${F('ȳ = '+frac('y₁ + … + yₙ','n'))}<p>Addiere die n Messwerte und teile die Summe durch ihre Anzahl. Erstelle eine neue Auswertungstabelle mit x und ȳ.</p><p>Bewahre Minimum und Maximum für <a href="#schritt-2">Schritt 2</a> auf. Rechne mit möglichst ungerundeten Zwischenergebnissen weiter.</p></article><article class="card example"><span class="tag">BEISPIEL · STRECKE BEI GLEICHER ZEIT</span><h3>Drei Messungen bei t = 1,0 s</h3>${table(['s₁','s₂','s₃','Mittelwert ȳ'],[['1,8 m','2,0 m','2,2 m','2,0 m']])}<p>ȳ = (1,8 + 2,0 + 2,2) m / 3 = 2,0 m.<br>Minimum: 1,8 m · Maximum: 2,2 m.</p></article></div>${detail('Auffälliger Wert – behalten oder ausschließen?','<ol><li>Prüfe auf Ablese-, Übertragungs-, Rechen- oder Durchführungsfehler.</li><li>Korrigiere nachweisbare Fehler. Wiederhole die Messung nach Möglichkeit.</li><li>Schließe einen Wert nur mit nachvollziehbarem Grund aus, etwa bei dokumentiertem Fehlstart der Stoppuhr oder verrutschtem Sensor. Begründe und dokumentiere den Ausschluss.</li></ol>'+box('Ohne erkennbaren Fehler bleibt der Wert enthalten.','Eine starke Abweichung allein rechtfertigt keinen Ausschluss.','warning'))}`);
sections.push(`<p class="lead">Ein gutes Diagramm macht den Zusammenhang sichtbar und zeigt zugleich, wie stark die Werte streuen.</p><article class="card"><h3>Achsen & Skalierung</h3><p>Plane das ganze Diagramm, bevor du die Achsen zeichnest. Gehe dabei in dieser Reihenfolge vor:</p><ol class="drawing-steps"><li><strong>Wertebereich bestimmen.</strong> Suche für beide Größen die kleinsten und größten Werte heraus. Berücksichtige auch Minimum und Maximum aus Wiederholungsmessungen sowie die Grenzen bekannter Unsicherheiten in x- und y-Richtung. Alles muss später in das Diagramm passen.</li><li><strong>Größen den Achsen zuordnen.</strong> Waagerecht: die unabhängig veränderte Größe (oft die Zeit). Senkrecht: die abhängige Größe.</li><li><strong>Verfügbaren Platz einplanen.</strong> Prüfe, wie viel beschreibbare Fläche auf dem Blatt zur Verfügung steht, und wähle passend dazu Hoch- oder Querformat. Ein Diagramm, an dem du Messdaten auswertest, sollte möglichst groß sein: auf einem A4-Blatt nach Möglichkeit mindestens die Hälfte der gesamten Blattfläche, besser nahezu den gesamten beschreibbaren Bereich. Plane dabei Platz für Zahlen, Achsenbeschriftungen und Pfeilspitzen ein.</li><li><strong>Ursprung festlegen.</strong> Für die hier verwendeten Diagramme ist der Schnittpunkt der Achsen der Ursprung (0|0). Der darzustellende Bereich muss deshalb auf beiden Achsen auch die 0 enthalten. Bei ausschließlich positiven Werten liegt der Ursprung unten links; bei negativen Werten brauchst du entsprechend Platz links davon bzw. darunter.</li><li><strong>Skalierungen und Achsenlängen aufeinander abstimmen.</strong> Zähle die verfügbaren großen Kästchen in waagerechter und senkrechter Richtung. Wähle für jede Achse gut ablesbare Schritte, z. B. 0,5; 1; 2 oder 5 Einheiten je großem Kästchen. Beide Achsen dürfen unterschiedlich skaliert sein. Prüfe, wie viele Kästchen du damit für den gesamten Wertebereich einschließlich 0 und aller Balken brauchst. Nutze die Fläche gut aus und lass bis zu den Pfeilspitzen etwas Platz. Passe die Skalierungen bei Bedarf an, bevor du zeichnest.</li><li><strong>Achsen zeichnen und einteilen.</strong> Zeichne mit dem Lineal zwei senkrecht zueinander stehende Achsen in den geplanten Längen und mit Pfeilspitzen in positiver Richtung. Setze die Teilstriche entsprechend der gewählten Skalierungen und trage die Zahlenwerte ein. Gleiche Zahlenunterschiede müssen auf derselben Achse immer gleiche Abstände haben.</li><li><strong>Achsen beschriften und prüfen.</strong> Beschrifte die Achsen so, dass Messgröße und Einheit eindeutig dokumentiert sind, zum Beispiel „Zeit t in s“, „Zeit in s“ oder „t in s“. Prüfe vor dem Eintragen der Messpunkte noch einmal: Stimmen Ursprung, Zahlenwerte und Einheiten? Passen alle Werte samt Balken hinein und wird die verfügbare Fläche gut genutzt?</li></ol><p class="muted">Die Größenempfehlung gilt für Diagramme zur Auswertung auf Papier. Eine kleine Skizze, die nur einen Verlauf veranschaulicht, erfüllt einen anderen Zweck.</p></article><article class="card"><h3>Messpunkte & Balken</h3><div id="errorPlot" class="plot"></div><p>Markiere Einzelwerte bzw. Mittelwerte als <strong>kleine Kreuze</strong>. Verbinde die Messpunkte zunächst nicht miteinander.</p><p>Bei Wiederholungsmessungen: Minimum und Maximum markieren, senkrecht mit kurzen Endstrichen verbinden und den Mittelwert auf dem Balken markieren.</p></article>${detail('Bekannte Messunsicherheit einzeichnen',`<p>Bei y ± Δy reicht der Fehlerbalken von y − Δy bis y + Δy. Bekannte Unsicherheiten der x-Werte stellst du entsprechend waagerecht dar.</p>`)}${box('Spannweite ≠ Messunsicherheit','Der beobachtete Bereich zwischen Minimum und Maximum ist nicht automatisch eine Messunsicherheit. Beschrifte eindeutig, was deine Balken darstellen.','warning')}`);
sections.push(`<p class="lead">Achte zuerst darauf, ob der Verlauf eine Gerade oder eine gekrümmte Kurve ist: Proportionale und lineare Zusammenhänge ergeben Geraden; antiproportionale, quadratische und exponentielle Zusammenhänge ergeben gekrümmte Kurven. Wähle einen Funktionstyp und vergleiche Merkmale, Prüfverfahren und Parameter.</p><div id="funktionsvergleich" class="card"><div class="type-tabs" role="tablist" aria-label="Funktionstypen"></div><div id="typePanel" role="tabpanel" tabindex="0"></div></div>${box('Der Ausschnitt kann täuschen.','Scheitelpunkt und Achsenschnittpunkte sind nicht immer sichtbar. Verschiedene Funktionstypen können ähnlich aussehen. Das Diagramm liefert eine Vermutung, keinen Nachweis. Prüfe sie in <a href="#schritt-4">Schritt 4</a>.','warning')}`);
sections.push(`<p class="lead">Prüfe zuerst den vermuteten Funktionstyp. Nutze anschließend die berechneten Prüfgrößen für eine erste analoge Näherung und leite dabei die Einheiten der Parameter her. Für quadratische Zusammenhänge ist kein analoges Verfahren zur Parameterbestimmung vorgesehen.</p>${box('Bewusst vereinfachte Näherungen','Die analogen Verfahren sind erste Näherungen und keine rechnerischen Regressionen. Um die Parameter möglichst genau zu bestimmen, nutze die Regression in <a href="#schritt-5">Schritt 5</a>.')}${proofGuide.html()}${box('Wie konstant ist „annähernd konstant“?','Die Beispiele zeigen zum Lernen exakt passende Werte. Echte Messwerte sind nicht exakt. Beurteile Abweichungen unter Berücksichtigung ihrer Unsicherheit. Es gibt keine pauschale zulässige Prozentabweichung. Systematische Veränderungen der Prüfgrößen können gegen das Modell sprechen; starke Schwankungen musst du im Verhältnis zur Messunsicherheit beurteilen. Eine passende Prüfgröße stützt die Vermutung, beweist aber allein kein physikalisches Gesetz.')}`);
sections.push(`<p class="lead">Nach der Prüfung und der ersten analogen Näherung in <a href="#schritt-4">Schritt 4</a> kannst du die Parameter mit einer Regression rechnerisch bestimmen. Hier findest du den im Kurs verwendeten Weg mit GeoGebra CAS.</p>${box('Rechnerische Anpassung an Messdaten','Eine Regression bestimmt die Parameter durch ein rechnerisches Anpassungsverfahren. Auch sie beschreibt den Zusammenhang bei Messdaten näherungsweise; die Genauigkeit der Parameter ist durch die Messgenauigkeit begrenzt. Vergleiche die Anpassung mit dem Diagramm und berücksichtige die Streuung bzw. Unsicherheit.') }<article class="card" id="geogebra"><span class="tag">DIGITALES VERFAHREN</span><h3>Regression mit GeoGebra CAS</h3><ol class="steps-inline"><li>Werte unter <strong>„Tabelle“</strong> eingeben.</li><li>Oben über die drei Punkte <strong>„Regression“</strong> auswählen.</li><li>Den passenden Regressionstyp einstellen.</li></ol><p>Dies ist der im Kurs verwendete Bedienweg.</p>${table(['Vermuteter Zusammenhang','Regressionstyp','Erwartung'],[['Proportional','Linear','Achsenabschnitt annähernd 0'],['Antiproportional','Potenz','Exponent annähernd −1'],['Linear','Linear','Form y = mx + b'],['Quadratisch','Quadratisch','Form y = ax² + bx + c'],['Exponentiell','Exponentiell','Passend zur Form a · bˣ']])}${box('Die Regression erzwingt das Modell nicht.','Die lineare Regression erzwingt keinen Ursprungsschnitt, die Potenzregression keinen Exponenten −1. Ändere ausgegebene Gleichungen nicht einfach entsprechend ab. Prüfe die Anpassung anhand des Diagramms und der Streuung bzw. Unsicherheit.','warning')}<p class="muted">Die Oberfläche kann je nach App-Version variieren. Konkrete GeoGebra-Screenshots sind deshalb hier nicht enthalten.</p></article>`);
sections.push(`<p class="lead">Runde erst am Ende. Ersetze x und y durch die tatsächlichen Formelzeichen und zeige mit den Einheiten, was deine Gleichung bedeutet.</p><div class="two-col"><article class="card"><h3>Signifikante Stellen</h3><p>Zähle ab der ersten von null verschiedenen Ziffer. Abschließende Nullen können Genauigkeit ausdrücken.</p>${F('2,34 → 3 Stellen<br>0,0234 → 3 Stellen<br>1,000 → 4 Stellen')}<p><strong>Zwei bis drei signifikante Stellen</strong> können ein Ausgangspunkt für das Runden sein. Ob das für die einzelnen Parameter sinnvoll ist, kannst du mit der <a href="#genauigkeit">Wirkung der letzten Stelle abschätzen</a>. Verwende Zwischenergebnisse möglichst ungerundet.</p></article><article class="card"><h3>Aus x und y wird Physik</h3><p>Setze z. B. Zeit t und Strecke s ein. Die Einheiten beziehen sich auf die bei der Dateneingabe verwendeten Einheiten.</p>${box('Eine Gleichung muss in den Einheiten stimmen.','Beide Seiten brauchen dieselbe Einheit. Bei Summen gilt das für jeden Summanden. [x] bezeichnet hier die Einheit von x.')}</article></div><div id="genauigkeit">${detail('Vertiefung: Was bewirkt die letzte Stelle?',`<span class="tag">EINFACHE ABSCHÄTZUNG OHNE FEHLERRECHNUNG</span><p>Übertrage die Stellenzahl der Messwerte nicht automatisch auf alle Parameter. Frage stattdessen: <strong>Wie stark würde ein Schritt an dieser Stelle den berechneten Messwert verändern?</strong> Die folgende Faustregel gilt hier für proportionale, lineare, antiproportionale und quadratische Zusammenhänge.</p><ol><li><strong>Den ungünstigsten Messwert auswählen.</strong> Überlege beim betroffenen Summanden, ob eine Änderung des Parameters bei großen oder kleinen x-Werten stärker wirkt. Verwende den passenden x-Wert aus deinen Messungen. Die Zuordnung findest du unten.</li><li><strong>Eine Rundungsstelle ausprobieren.</strong> Ein Schritt an dieser Stelle ist zum Beispiel 0,01 m/s oder 0,001 m/s. Betrachte nur diesen Schritt, nicht den ganzen Parameter.</li><li><strong>Seine Wirkung ausrechnen.</strong> Setze den ausgewählten x-Wert ein und berechne, wie stark dieser Stellenschritt den Summanden verändern würde.</li><li><strong>Mit der Messunsicherheit vergleichen.</strong> Ist die Wirkung kleiner als die Unsicherheit der y-Messung, ist die Stelle ausreichend fein. Ist sie größer oder gleich groß, gehe eine Stelle weiter nach rechts und rechne noch einmal.</li><li><strong>Den Parameter auf diese Stelle runden.</strong> Verwende die erste ausreichend feine Stelle. Die ungerundeten Parameter behältst du für weitere Rechnungen.</li></ol><h4>Beispiel: Wie viele Stellen braucht eine Steigung?</h4><p>Die Strecke wurde auf etwa <strong>1 cm genau</strong> gemessen. Die längste verwendete Messzeit beträgt <strong>10 s</strong>. Für den Summanden m · t wirkt sich eine Änderung von m bei dieser längsten Zeit am stärksten aus.</p>${table(['Ausprobierte Rundungsstelle von m','Wirkung nach 10 s','Beurteilung'],[['0,01 m/s','0,01 m/s · 10 s = 0,10 m = 10 cm','Zu grob: größer als 1 cm.'],['0,001 m/s','0,001 m/s · 10 s = 0,01 m = 1 cm','Noch nicht kleiner als 1 cm.'],['0,0001 m/s','0,0001 m/s · 10 s = 0,001 m = 0,1 cm','Ausreichend fein: kleiner als 1 cm.']])}<p><strong>Also runden wir die Steigung in diesem Beispiel auf 0,0001 m/s.</strong> Bei einer anderen Messdauer oder Messunsicherheit kann eine andere Stelle sinnvoll sein.</p><h4>Was setzt du bei den anderen Summanden ein?</h4>${table(['Summand','Passenden x-Wert auswählen','Wirkung des Stellenschritts ausrechnen'],[['ax oder mx','Den größten verwendeten x-Wert nehmen.','Den Stellenschritt mit diesem x-Wert multiplizieren.'],['ax²','Den größten verwendeten x-Wert nehmen und quadrieren.','Den Stellenschritt mit diesem x² multiplizieren.'],[F(frac('a','x')),'Den kleinsten verwendeten positiven x-Wert nehmen; x = 0 ist ausgeschlossen.','Den Stellenschritt durch diesen x-Wert teilen.'],['Konstanter Summand, z. B. b oder c','Kein x nötig: Er wirkt überall gleich.','Den Stellenschritt direkt mit der y-Messunsicherheit vergleichen. Vorher dieselbe Einheit verwenden.']])}<p class="muted">Die Auswahl „größter“ bzw. „kleinster“ x-Wert gilt hier für positive Messwerte. Falls auch negative Werte vorkommen: Bei x und x² ist der am weitesten von null entfernte Messwert maßgeblich; bei 1/x der von null verschiedene Messwert, der am nächsten an null liegt.</p>${box('Eine bewusst vorsichtige Faustregel','Beim normalen Runden ändert sich der Parameter höchstens um einen halben Stellenschritt. Hier rechnen wir zur einfachen Abschätzung mit einem ganzen Schritt. Die Regel beurteilt nur die zusätzliche Veränderung durch das Runden; sie berechnet keine Parameterunsicherheit und beweist keinen exakt verschwindenden Achsenabschnitt. Bei mehreren gerundeten Parametern können sich ihre Wirkungen addieren. Die Abschätzung bezieht sich auf den untersuchten Messbereich.')}`)}</div><article class="card" id="einheiten"><h3>Einheiten herleiten statt auswendig lernen</h3><p>In <a href="#schritt-4">Schritt 4</a> hast du die Parametereinheiten bereits aus den analogen Rechenwegen hergeleitet. Prüfe damit nun auch die Regressionsgleichung. Bei quadratischen Zusammenhängen ergeben sich die Einheiten aus den einzelnen Termen. Die folgende Übersicht fasst die Herleitungen zusammen:</p>${table(['Gleichung','Herleitung und Einheiten'],[['y = ax','a = y/x → [a] = [y]/[x]. Das Produkt ax hat damit die Einheit von y.'],[F('y = '+frac('a','x')),'a = yx → [a] = [y][x]. Beim Teilen durch x bleibt die Einheit von y.'],['y = mx + b','[mx] = [y] → [m] = [y]/[x]. Weil b addiert wird, gilt [b] = [y].'],['y = ax² + bx + c','[ax²] = [bx] = [c] = [y]. Daher [a] = [y]/[x]², [b] = [y]/[x], [c] = [y].']])}</article><article class="card example"><span class="tag">BEISPIEL · DREI SIGNIFIKANTE STELLEN</span><h3>Zeit in Sekunden, Strecke in Metern</h3>${F('y = 1,23784x² + 0,41632x + 0,08271')}<p>Mit den physikalischen Formelzeichen und gerundeten Parametern:</p>${F('s(t) = 1,24 '+frac('m','s²')+' t²<br> + 0,416 '+frac('m','s')+' t + 0,0827 m')}<p>Erster Term: (m/s²) · s² = m. Zweiter Term: (m/s) · s = m. Der konstante Term hat ebenfalls die Einheit Meter. Jeder Summand passt.</p></article>${detail('Besonderheit exponentieller Funktionen',`<p>Der Vorfaktor a hat die Einheit von y. <strong>Basis und Exponent sind einheitenlos.</strong> Bei einer Zeitgröße schreibst du beispielsweise:</p>${F('U(t) = 5,00 V · 0,85<sup>t/(1 s)</sup>')}<p>t/(1 s) ist einheitenlos. Der Faktor 0,85 gilt pro Sekunde. Die Bezugseinheit im Exponenten entspricht der bei der Regression verwendeten Einheit der unabhängigen Größe.</p>`)}`);
document.querySelector('#stepNav').innerHTML=names.map((n,i)=>`<a href="#schritt-${i+1}" data-step="${i+1}"><span class="nav-num">0${i+1}</span><span class="nav-title">${n}</span></a>`).join('');
document.querySelector('#overview').innerHTML=names.map((n,i)=>`<a class="overview-card" href="#schritt-${i+1}"><span class="overview-num">0${i+1}</span><h3>${n}</h3><p>${descriptions[i]}</p><span class="arrow" aria-hidden="true">↗</span></a>`).join('');
document.querySelector('#content').innerHTML=sections.map((s,i)=>`<section class="step" id="schritt-${i+1}"><div class="section-kicker">SCHRITT 0${i+1} / 06</div><h2>${names[i]}</h2><details class="knowledge" id="wissen-${i+1}"><summary><span>Wissen</span><span class="knowledge-summary">Erklärungen &amp; Beispiele</span></summary><div class="knowledge-content">${s}</div></details><a class="back-top" href="${i<5?'#schritt-'+(i+2):'#'}">${i<5?'Weiter: '+names[i+1]+' →':'Zur Übersicht ↑'}</a></section>`).join('');
const types=[
{name:'Proportional',eq:'y = ax',desc:'Eine Gerade durch den Ursprung.',note:'Proportionalität ist der Sonderfall einer linearen Funktion mit b = 0.',check:'yᵢ/xᵢ annähernd konstant; x = 0 beim Dividieren auslassen.',fn:x=>.7*x},
{name:'Linear',eq:'y = mx + b',desc:'Eine Gerade mit y-Achsenabschnitt b.',note:'m ist die Steigung. Bei b = 0 ist der Zusammenhang proportional.',check:'Steigungen aufeinanderfolgender Punkte annähernd konstant.',fn:x=>.55*x+1.1},
{name:'Antiproportional',eq:'y = '+frac('a','x')+', a ≠ 0',desc:'Eine Kurve, die sich beiden Achsen annähert, ohne sie zu schneiden (Hyperbel).',note:'Bei a > 0 ist sie im positiven Bereich fallend und wird zunehmend flacher. Bei x = 0 ist die Funktion nicht definiert. Oft ist auch der zugrunde liegende physikalische Zusammenhang für x = 0 nicht sinnvoll definiert, etwa weil das im Modell vorausgesetzte Objekt unter dieser Bedingung gar nicht existieren kann. Beispiel: Für eine feste Gasmenge bei gleichbleibender Temperatur beschreibt p = a/V den Zusammenhang von Druck und Volumen. Ein Volumen V = 0 ist für diese Gasmenge kein sinnvoller Zustand. Ob x = 0 physikalisch sinnvoll ist, musst du jeweils am betrachteten Modell prüfen.',check:'Produkte xᵢyᵢ annähernd konstant.',fn:x=>2.8/x},
{name:'Quadratisch',eq:'y = ax² + bx + c, a ≠ 0',desc:'Eine Kurve, die parabelförmig verläuft. Sie besitzt einen Scheitelpunkt und eine zur y-Achse parallele Symmetrieachse durch diesen Punkt.',note:'Für a > 0 nach oben, für a < 0 nach unten geöffnet. y-Achsenabschnitt c; je nach Lage kein, ein oder zwei gemeinsame Punkte mit der x-Achse.',check:'Bei gleichen x-Abständen: zweite Differenzen annähernd konstant.',fn:x=>.35*(x-2.2)**2+.6},
{name:'Exponentiell',eq:'y = a · bˣ',desc:'Eine Kurve, die die x-Achse nicht schneidet und sich ihr in einer Richtung annähert.',note:'a ≠ 0, b > 0, b ≠ 1. y-Achsenabschnitt a. Für a > 0: Wachstum bei b > 1, Abnahme bei 0 < b < 1.',check:'Bei gleichen x-Abständen: Quotienten yᵢ₊₁/yᵢ annähernd konstant.',fn:x=>.45*1.55**x}
];
function plot(fn,{hero=false,bars=false}={}){let lines='';for(let i=1;i<6;i++)lines+=`<path d="M${40+i*48} 20V250 M40 ${250-i*38}H330" stroke="#dce4df" stroke-width="1"/>`;let curve='';if(fn){for(let x=.02;x<=5.8;x+=.035){const y=fn(x);curve+=(y>=0&&y<=5.9?(curve?' L':'M')+(40+x*48).toFixed(1)+' '+(250-y*38).toFixed(1):'');}}let marks='';if(hero||bars){[1,2,3,4,5].forEach((x,i)=>{let y=hero?.12*x*x+.45*x:[1,1.8,2.3,3.5,4.1][i];let px=40+x*48,py=250-y*38;const len=bars?15:8;marks+=`<path d="M${px} ${py-len}V${py+len} M${px-5} ${py-len}H${px+5} M${px-5} ${py+len}H${px+5}" stroke="#ba632f" stroke-width="2"/><path d="M${px-4} ${py-4}l8 8m0-8l-8 8" stroke="#163c3a" stroke-width="2.5"/>`;});}return `<svg viewBox="0 0 360 290" role="img" aria-label="${bars?'Beispiel: Mittelwerte mit Balken vom Minimum bis zum Maximum':'Schematischer Funktionsverlauf'}"><defs><clipPath id="clip-${hero?'hero':bars?'bars':'type'}"><rect x="40" y="20" width="290" height="230"/></clipPath></defs>${lines}${bars?[1,2,3,4,5].map(i=>`<text x="${40+i*48}" y="266" text-anchor="middle" font-size="11" fill="#45635f">${i}</text><text x="30" y="${254-i*38}" text-anchor="end" font-size="11" fill="#45635f">${i}</text>`).join(''):''}<path d="M40 15V250H340" fill="none" stroke="#45635f" stroke-width="1.5"/><path d="M40 15L36 23H44Z M340 250L332 246V254Z" fill="#45635f"/><text x="24" y="268" fill="#45635f" font-size="12">0</text><text x="337" y="271" text-anchor="end" fill="#45635f">${bars?'t in s':'x'}</text><text x="10" y="16" fill="#45635f">${bars?'s in m':'y'}</text><g clip-path="url(#clip-${hero?'hero':bars?'bars':'type'})">${curve?`<path d="${curve}" fill="none" stroke="#ba632f" stroke-width="3"/>`:''}${marks}</g>${hero?'<text x="70" y="40" fill="#45635f" font-size="12" letter-spacing="2">MESSEN. ERKENNEN. VERSTEHEN.</text>':''}</svg>`;}
document.querySelector('#heroPlot').innerHTML=plot(x=>.12*x*x+.45*x,{hero:true});
document.querySelector('#errorPlot').innerHTML=plot(null,{bars:true});
const tabs=document.querySelector('.type-tabs');tabs.innerHTML=types.map((t,i)=>`<button role="tab" id="type-${i}" aria-controls="typePanel" aria-selected="${i===0}" tabindex="${i===0?0:-1}" data-type="${i}">${t.name}</button>`).join('');
function selectType(i){const t=types[i];tabs.querySelectorAll('button').forEach((b,n)=>{b.setAttribute('aria-selected',String(i===n));b.tabIndex=i===n?0:-1});document.querySelector('#typePanel').setAttribute('aria-labelledby',`type-${i}`);document.querySelector('#typePanel').innerHTML=`<div class="model-layout"><div class="plot">${plot(t.fn)}<p class="muted">Schematischer Beispielverlauf im positiven Bereich.</p></div><div class="model-info"><span class="tag">${t.name.toUpperCase()}</span>${F(t.eq)}<h3>${t.desc}</h3><p>${t.note}</p><div class="callout note"><strong>So prüfst du die Vermutung</strong><p>${t.check}</p><a href="#pruefen-${t.name.toLowerCase()}">Prüfen & erste Näherung →</a></div></div></div>`;}
tabs.addEventListener('click',e=>{const b=e.target.closest('[data-type]');if(b)selectType(+b.dataset.type)});tabs.addEventListener('keydown',e=>{if(['ArrowRight','ArrowLeft','Home','End'].includes(e.key)){e.preventDefault();let n=+document.activeElement.dataset.type;n=e.key==='Home'?0:e.key==='End'?4:(n+(e.key==='ArrowRight'?1:4))%5;selectType(n);tabs.children[n].focus();}});selectType(0);
const menu=document.querySelector('#menuToggle');menu.addEventListener('click',()=>{const on=document.body.classList.toggle('nav-open');menu.setAttribute('aria-expanded',String(on))});document.querySelector('.sidebar').addEventListener('click',e=>{if(e.target.closest('a')){document.body.classList.remove('nav-open');menu.setAttribute('aria-expanded','false')}});
const search=document.querySelector('#search');search.addEventListener('input',()=>{const q=search.value.trim().toLocaleLowerCase('de');let count=0;document.querySelectorAll('.step').forEach(s=>{const typeMatch=s.id==='schritt-3'&&types.some(t=>(t.name+' '+t.eq+' '+t.desc+' '+t.note+' '+t.check).toLocaleLowerCase('de').includes(q));const match=!q||typeMatch||s.textContent.toLocaleLowerCase('de').includes(q);s.hidden=!match;if(match)count++;s.querySelectorAll('details').forEach(d=>{if(q&&match)d.open=true;else if(!q)d.open=false})});if(q){const found=types.findIndex(t=>(t.name+' '+t.eq+' '+t.desc+' '+t.note+' '+t.check).toLocaleLowerCase('de').includes(q));if(found>=0)selectType(found);}proofGuide.search(q);document.querySelector('#overview').hidden=!!q;document.querySelector('#searchStatus').textContent=q?`${count} von 6 Schritten${count===0?' · anderen Suchbegriff versuchen':''}`:'';});
document.addEventListener('click',e=>{const a=e.target.closest('a[href^="#"]');if(a&&search.value){search.value='';search.dispatchEvent(new Event('input'));}});
const observer=new IntersectionObserver(entries=>{entries.forEach(e=>{if(e.isIntersecting)document.querySelectorAll('#stepNav a').forEach(a=>{const active=a.hash==='#'+e.target.id;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','step');else a.removeAttribute('aria-current')})})},{rootMargin:'-15% 0px -65% 0px'});document.querySelectorAll('.step').forEach(s=>observer.observe(s));
const heroObserver=new IntersectionObserver(entries=>{if(entries.some(e=>e.isIntersecting)){document.querySelectorAll('#stepNav a').forEach(a=>{a.classList.remove('active');a.removeAttribute('aria-current')})}});heroObserver.observe(document.querySelector('.hero'));

proofGuide.init();
document.addEventListener('click',e=>{const a=e.target.closest('a[data-model]');if(a){const i=types.findIndex(t=>t.name.toLowerCase()===a.dataset.model);if(i>=0)selectType(i);}});

// Deep links into an explanation reveal its containing knowledge panel.
function revealKnowledge(hash){
  if(!hash||hash==='#')return;
  const target=document.getElementById(decodeURIComponent(hash.slice(1)));if(!target)return;
  for(let parent=target;parent;parent=parent.parentElement)if(parent.tagName==='DETAILS')parent.open=true;
}
window.addEventListener('hashchange',()=>revealKnowledge(location.hash));
document.addEventListener('click',e=>{const a=e.target.closest('a[href^="#"]');if(a)revealKnowledge(a.hash);});
revealKnowledge(location.hash);
